<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Mail/ExternalAccount.php';require dirname(__DIR__).'/app/Mail/MessageBody.php';require dirname(__DIR__).'/app/Mail/ImapClient.php';
use TNL\Mail\ExternalAccount;use TNL\Mail\MessageBody;use TNL\Mail\MimeView;use TNL\UI\MessageHtml;
function checkRich(bool $v,string $m):void {if(!$v)throw new RuntimeException($m);echo "PASS: $m\n";}
$db=new PDO('sqlite::memory:');$store=new ExternalAccount($db,sys_get_temp_dir());$store->recordSent('employee:1','peer@example.test','Same subject','<p><b>Hola</b></p><script>alert(1)</script>','<a@example.test>',[],'html');$store->recordSent('employee:1','peer@example.test','Same subject','Reply','<b@example.test>',['in_reply_to'=>'<a@example.test>','references'=>'<a@example.test>']);$store->recordSent('employee:2','peer@example.test','Same subject','Secret','<c@example.test>',['references'=>'<a@example.test>']);$store->recordSent('employee:1','peer@example.test','Same subject','Unrelated','<d@example.test>');
$m=$store->sentView('employee:1',1,'me@example.test');checkRich(str_contains($m['html'],'<b>Hola</b>')&&!str_contains($m['html'],'script'),'sent HTML survives storage and active content is stripped');checkRich($store->sentView('employee:2',1,'other@example.test')===null,'opening sent requires owner');checkRich(count($store->related('employee:1',$m['headers']))===2,'conversation joins IDs without mixing owners or identical subjects');checkRich($store->sentMessage('employee:1',2)['format']==='plain','legacy plain sent messages remain plain');
$md=MessageBody::html("# Título\n\n**Negrita**\n\n<script>alert(1)</script>\n\n[x](javascript:alert(1))",'markdown');checkRich(str_contains($md,'<h1>')&&str_contains($md,'<strong>')&&!str_contains($md,'<script>')&&!str_contains($md,'href="javascript:'),'Markdown is styled without active HTML or javascript links');
$png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=');$raw="Content-Type: multipart/related; boundary=b\r\n\r\n--b\r\nContent-Type: text/html\r\n\r\n<img src=photo.png>\r\n--b\r\nContent-Type: image/png\r\nContent-Location: photo.png\r\nContent-Transfer-Encoding: base64\r\n\r\n".base64_encode($png)."\r\n--b--\r\n";$parsed=MimeView::extract($raw);checkRich(str_contains(MessageHtml::fragment($parsed['html'],$parsed['inline_images']),'<img src="data:image/png'),'Content-Location images render without CID');$data='data:image/png;base64,'.base64_encode($png);checkRich(str_contains(MessageHtml::fragment('<img src="'.$data.'">'),'<img src='),'valid raster data images render');checkRich(!str_contains(MessageHtml::fragment('<img src="data:image/svg+xml;base64,PHN2Zz4=">'),'<img'),'data SVG is rejected');checkRich(str_contains(MessageHtml::fragment('<img src="//images.example.test/p.png">',[],true),'https://images.example.test'),'protocol-relative external images use HTTPS');checkRich(str_contains(MimeView::extract("Content-Type: text/markdown\r\n\r\n# Heading")['html'],'<h1>'),'MIME text/markdown is rendered automatically');
